#!/usr/bin/env python3
#
# Format XHTML generated by groff -Txhtml for websites
#
# Usage: groff -Txhtml -P-l something.man | python3 fix-groff-xhtml.py OUTPUT-FILE
#
# (C) Copyright 2025 Dave Beckett
#

import html
import os
import re
import sys
from datetime import date

# Module-level constants for titles
RAPTOR_TITLE = "Raptor RDF Parser Toolkit"
REDLAND_TITLE = "Redland RDF Application Framework"
RASQAL_TITLE = "Rasqal RDF Query Library"

REPLACEMENTS = [
    ("<title>libraptor</title>", f"<title>{RAPTOR_TITLE} - Raptor API</title>"),
    ('<h1 align="center">libraptor</h1>', f"<h1>{RAPTOR_TITLE} - Raptor API</h1>"),
    ("<h1>libraptor</h1>", f"<h1>{RAPTOR_TITLE} - Raptor API</h1>"),
    ("<title>libraptor2</title>", f"<title>{RAPTOR_TITLE} - Raptor API</title>"),
    ("<h1>libraptor2</h1>", f"<h1>{RAPTOR_TITLE} - Raptor API</h1>"),
    (
        "<title>rapper</title>",
        f"<title>{RAPTOR_TITLE} - Raptor RDF parser utility</title>",
    ),
    (
        '<h1 align="center">rapper</h1>',
        f"<h1>{RAPTOR_TITLE} - Raptor RDF parser utility</h1>",
    ),
    (
        "<h1>rapper</h1>",
        f"<h1>{RAPTOR_TITLE} - Raptor RDF parser utility</h1>",
    ),
    (
        "<title>rdfproc</title>",
        f"<title>{REDLAND_TITLE} - Redland RDF processor utility</title>",
    ),
    (
        '<h1 align="center">rdfproc</h1>',
        f"<h1>{REDLAND_TITLE} - Redland RDF processor utility</h1>",
    ),
    (
        "<h1>rdfproc</h1>",
        f"<h1>{REDLAND_TITLE} - Redland RDF processor utility</h1>",
    ),
    ("<title>librasqal</title>", f"<title>{RASQAL_TITLE} - Rasqal API</title>"),
    ('<h1 align="center">librasqal</h1>', f"<h1>{RASQAL_TITLE} - Rasqal API</h1>"),
    ("<h1>librasqal</h1>", f"<h1>{RASQAL_TITLE} - Rasqal API</h1>"),
    (
        "<title>roqet</title>",
        f"<title>{RASQAL_TITLE} - Rasqal RDF query utility</title>",
    ),
    (
        '<h1 align="center">roqet</h1>',
        f"<h1>{RASQAL_TITLE} - Rasqal RDF query utility</h1>",
    ),
    (
        "<h1>roqet</h1>",
        f"<h1>{RASQAL_TITLE} - Rasqal RDF query utility</h1>",
    ),
]


def make_xml_id(value):
    """Turn text into a legal XML ID (an NCName)."""
    xml_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", value).strip("_")
    if not re.match(r"[A-Za-z_]", xml_id):
        xml_id = f"section_{xml_id}"
    return xml_id


def normalize_headings(document):
    """Replace groff's generated heading IDs with stable text-based IDs."""
    heading_ids = {}
    used_ids = set()

    def replace_heading(match):
        level, heading_number, contents = match.groups()
        label = html.unescape(re.sub(r"<[^>]+>", "", contents))
        label = re.sub(r"\s+", " ", label).strip()
        slug = make_xml_id(label)
        if level == "2":
            slug = slug.upper()
        # IDs must be unique within the document.
        base, count = slug, 2
        while slug in used_ids:
            slug = f"{base}_{count}"
            count += 1
        used_ids.add(slug)
        heading_ids[heading_number] = slug
        return f'<h{level} id="{slug}">{contents}</h{level}>'

    document, count = re.subn(
        r'<h([2-6]) id="heading(\d+)">(.*?)</h\1>',
        replace_heading,
        document,
        flags=re.DOTALL,
    )
    if not count:
        raise ValueError(
            'no <hN id="headingN"> headings found; unexpected groff -Txhtml output'
        )
    for heading_number, slug in heading_ids.items():
        document = document.replace(
            f'href="#heading{heading_number}"', f'href="#{slug}"'
        )
    return document


def normalize_doctype(document):
    """Replace groff's XHTML 1.1 plus MathML doctype with XHTML 1.0."""
    doctype = """<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN"
    "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">"""
    return re.sub(
        r'<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1\.1 plus MathML 2\.0//EN"\s+'
        r'"[^"]+"\s+\[<!ENTITY mathml "[^"]+">\]>',
        doctype,
        document,
    )


def normalize_encoding(document):
    """Declare UTF-8, which is how the output is written.

    groff 1.23 declares us-ascii and groff 1.24 declares UTF-8.
    """
    document = re.sub(
        r'(<\?xml[^>]*encoding=")[^"]+(")', r"\1UTF-8\2", document, count=1
    )
    return re.sub(
        r'(<meta http-equiv="Content-Type" content="text/html; charset=)[^"]+(")',
        r"\1UTF-8\2",
        document,
        count=1,
        flags=re.IGNORECASE,
    )


def decode_named_entities(document):
    """Turn named HTML entities into UTF-8 text while keeping XML entities."""
    xml_entities = {"amp", "lt", "gt", "quot", "apos"}

    def replace_entity(match):
        if match.group(1) in xml_entities:
            return match.group(0)
        return html.unescape(match.group(0))

    return re.sub(r"&([A-Za-z][A-Za-z0-9]+);", replace_entity, document)


def replace_xml_id_attr(match):
    """
    A replacer function for re.sub to make id and a name values legal XML IDs.
    """
    return f'{match.group(1)}="{make_xml_id(html.unescape(match.group(2)))}"'


def main():
    """
    Main function to process XHTML from stdin and write to a file.
    """
    progname = os.path.basename(sys.argv[0])

    if len(sys.argv) < 2:
        print(f"USAGE: {progname} OUTPUT-FILE", file=sys.stderr)
        sys.exit(1)

    output_file = sys.argv[1]

    try:
        document = sys.stdin.read()
        document = normalize_doctype(document)
        document = normalize_encoding(document)
        document = normalize_headings(document)
        document = decode_named_entities(document)
    except ValueError as e:
        print(f"{progname}: {e}", file=sys.stderr)
        sys.exit(1)

    output = []
    title_replaced = False
    for line in document.splitlines(keepends=True):
        # Apply all title and h1 replacements
        for old, new in REPLACEMENTS:
            if old in line:
                line = line.replace(old, new)
                title_replaced = True

        # Skip link and meta tags, keeping the character encoding
        # declaration needed when the page is served as text/html.
        if re.match(r"^<(?:link|meta)\b", line, re.IGNORECASE) and not re.search(
            r'http-equiv="Content-Type"', line, re.IGNORECASE
        ):
            continue

        # Simplify body tag
        line = re.sub(r"^<body[^>]*>", "<body>", line)

        # Remove cols attribute
        line = re.sub(r' cols="\d+" ', " ", line)

        # Make id and anchor name attributes legal XML IDs
        line = re.sub(r'(\bid|<a name)="([^"]+)"', replace_xml_id_attr, line)

        # Linkify author
        line = re.sub(
            r"(Dave Beckett|Institute for Learning and Research Technology \(ILRT\)|University of Bristol) (?:- |)(https?://[^<\s]+)",
            r'<a href="\2">\1</a>',
            line,
        )

        # Add copyright before </body>.
        if "</body>" in line:
            year = date.today().year
            output.append(f"""
<p>Copyright 2002-{year} <a href="https://www.dajobe.org/">Dave Beckett</a><br />2002-2005 <a href="https://www.bristol.ac.uk/">University of Bristol</a></p>
""")

        output.append(line)

    if not title_replaced:
        print(
            f"{progname}: no known <title> or <h1> found; unexpected groff -Txhtml output",
            file=sys.stderr,
        )
        sys.exit(1)

    try:
        with open(output_file, "w", encoding="utf-8") as out_f:
            out_f.writelines(output)
    except OSError as e:
        print(f"{progname}: Cannot create {output_file} - {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
